{
  "groups": [
    {
      "group_id": "low_rate_lockin",
      "rule": "rate_type == 'fixed' and origination_year <= 2021.0 and mortgage_rate_pct < 3.0",
      "rationale": "Borrowers who secured historically low rates are highly motivated to retain their current lender to avoid a severe payment shock upon renewal."
    },
    {
      "group_id": "variable_rate_pressure",
      "rule": "rate_type == 'variable' and credit_score_band == '720_plus'",
      "rationale": "These borrowers have experienced immediate payment increases due to policy rate hikes but maintain strong credit profiles that provide them with significant refinancing leverage."
    },
    {
      "group_id": "distressed_insured",
      "rule": "insured_flag == True and credit_score_band in ['600_659', 'below_600']",
      "rationale": "Lower credit quality combined with insurance constraints limits these borrowers' ability to switch lenders, effectively trapping them in the current book."
    },
    {
      "group_id": "income_constrained_families",
      "rule": "n_children >= 2 and household_income_cad < 75000",
      "rationale": "Households with multiple children and restricted income have minimal budgetary flexibility to manage higher mortgage payments in an inflationary environment."
    },
    {
      "group_id": "high_equity_uninsured",
      "rule": "insured_flag == False and credit_score_band == '720_plus' and mortgage_balance_cad < 350000",
      "rationale": "High-equity borrowers with strong credit are prime targets for competitor acquisition and are the most likely to shop around for better market rates."
    },
    {
      "group_id": "labour_vulnerable_employed",
      "rule": "employment_status == 'self_employed' and credit_utilization_pct > 45.0",
      "rationale": "Self-employed individuals with high credit utilization face increased risk sensitivity and potential difficulty meeting strict income verification at new lenders."
    },
    {
      "group_id": "retiree_stable",
      "rule": "primary_borrower_age >= 60 and employment_status == 'retired'",
      "rationale": "Retired borrowers typically exhibit low mobility and prioritize stability over aggressive rate shopping during the renewal process."
    }
  ]
}
